print('\nTask row 50 label (A:F):')
print(50, row_vals(ws,50,1,6))

print('\nData row 20 headers:')
print(row_vals(data,20,1,data.max_column))
print('\nData row 21 headers/values:')
print(row_vals(data,21,1,data.max_column))
print('\nData rows 21-38 (non-empty cells shown):')
for r in range(21,39):
    vals=[]
    for c in range(1,data.max_column+1):
        v=data.cell(r,c).value
        if v is not None:
            vals.append(f'{get_column_letter(c)}={v!r}')
    print(f'Row {r}: ' + '; '.join(vals))

# Infer rows/cols: find Task years in Data headers rows 20/21 and codes in rows 21-38
series_codes=[]
for r in list(range(12,18))+list(range(19,25))+list(range(26,32)):
    v=ws.cell(r,4).value
    if v is not None:
        series_codes.append(v)
years=[ws.cell(10,c).value for c in range(8,13)]
print('\nInferred candidates:')
for hr in [20,21]:
    cols=[]
    for c in range(1,data.max_column+1):
        if data.cell(hr,c).value in years:
            cols.append(c)
    print(f'Header row {hr} matching Task years: {[get_column_letter(c) for c in cols]}')
for c in range(1,data.max_column+1):
    matches=[]
    for r in range(21,39):
        if data.cell(r,c).value in series_codes:
            matches.append(r)
    if matches:
        print(f'Code column candidate {get_column_letter(c)} ({c}) rows matched: {matches[:10]} count={len(matches)}')

