from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
out = '/root/output/result.xlsx'
wb = load_workbook(out, data_only=False)
ws = wb['Task']
print('Re-opened:', out)
print('Sheets:', wb.sheetnames)
required = ['H12', 'H35', 'H42', 'H50']
for cell in required:
    val = ws[cell].value
    print(cell, repr(val))
    if val is None:
        raise AssertionError(f'{cell} is None')
    if not (isinstance(val, str) and val.startswith('=')):
        raise AssertionError(f'{cell} is not a formula string: {val!r}')

# Additional targeted checks for formula coverage and sheet constraints
for r1, r2 in [(12,17),(19,24),(26,31)]:
    for r in range(r1, r2+1):
        for c in range(8,13):
            val = ws.cell(r,c).value
            if not (isinstance(val, str) and val.startswith('=INDEX(')):
                raise AssertionError(f'{get_column_letter(c)}{r} missing INDEX formula: {val!r}')
for r in range(35,41):
    for c in range(8,13):
        val = ws.cell(r,c).value
        if not (isinstance(val, str) and val.startswith('=')):
            raise AssertionError(f'{get_column_letter(c)}{r} missing formula: {val!r}')
for r in range(42,48):
    for c in range(8,13):
        val = ws.cell(r,c).value
        if not (isinstance(val, str) and val.startswith('=')):
            raise AssertionError(f'{get_column_letter(c)}{r} missing formula: {val!r}')
for c in range(8,13):
    val = ws.cell(50,c).value
    if not (isinstance(val, str) and val.startswith('=SUMPRODUCT(')):
        raise AssertionError(f'{get_column_letter(c)}50 missing weighted mean formula: {val!r}')
print('All targeted formula checks passed.')
print('Sample confirmations:')
for cell in ['H12','I12','H35','I35','H42','H43','H44','H45','H46','H47','H50']:
    print(cell, ws[cell].value)
